<script setup lang="ts">
import {computed} from 'vue';import {useQuacksStore} from '../../stores/quacks';import QuacksGlyph from './QuacksGlyph.vue';import UiButton from '../../components/UiButton.vue';
const game=useQuacksStore(),choice=computed(()=>game.mine?.pending),grouped=computed(()=>choice.value?.kind==='witch-trade'||choice.value?.options.some(o=>o.coin)),coins=computed(()=>[...new Set(choice.value?.options.map(o=>o.coin).filter((x):x is 'gold'|'copper'|'silver'=>!!x))]),options=computed(()=>grouped.value&&game.coinFilter?choice.value?.options.filter(o=>o.coin===game.coinFilter):choice.value?.options.filter(o=>!grouped.value||!o.coin));
const labels={gold:'金幣',copper:'銅幣',silver:'銀幣'};
</script>
<template><section v-if="choice" class="vue-quacks-choice"><h2>{{ choice.title }}</h2><template v-if="grouped&&!game.coinFilter"><p>先選擇要棄掉的女巫幣。</p><div class="vue-quacks-tabs"><button v-for="color in coins" :key="color" type="button" :disabled="!game.available||choice.options.filter(o=>o.coin===color).every(o=>o.disabled)" @click="game.coinFilter=color"><QuacksGlyph :resource="color"/>棄{{ labels[color] }}</button></div></template><template v-if="grouped&&game.coinFilter"><p>已選擇棄{{ labels[game.coinFilter as keyof typeof labels] }}，再選擇要拿的藥材。</p><UiButton icon="undo" label="重選女巫幣" :disabled="!game.available" @click="game.coinFilter=''"/></template><div class="vue-quacks-choice-grid"><button v-for="option in options" :key="option.id" type="button" :disabled="!game.available||option.disabled" @click="game.command('choice',{choiceId:choice.id,optionId:option.id})"><span v-if="option.ingredient" class="vue-quacks-tabs"><template v-for="(c,index) in option.ingredients||[option.ingredient]" :key="index"><template v-if="c.fromValue"><QuacksGlyph :chip="{color:c.fromColor||c.color,value:c.fromValue}"/>→</template><QuacksGlyph :chip="c" :size="48"/></template></span><strong>{{ option.label }}</strong><span v-if="option.cost" class="vue-quacks-tabs"><QuacksGlyph :resource="option.cost.resource" :size="24"/>−{{ option.cost.amount }}</span></button></div></section></template>
